var axios = require('axios');

class SaveBehavior {
  constructor(options) {
    this.getLocks = options.getLocks;
    this.config = options.config;
    this.editorContent = options.editorContent;
    this.editorState = options.editorState;
    this.editor = options.editor;
  }

  store(content) {
    if (!(this.config.data_storage.url || this.config.data_storage.save_handler)) {
      return;
    }

    if (this.getLocks() > 0) {
      return;
    }

    clearTimeout(this.timeout);
    this.timeout = setTimeout(() => this.checkforStore(content), this.config.data_storage.interval);
  }

  getTextFromEditor(content) {
    return content.blocks.map(o => o.text).join("\n");
  }

  getUrl() {
    const url = this.config.data_storage.url;
    if (typeof url === "function") {
      return url();
    } else {
      return url;
    }
  }

  getMethod() {
    const method = this.config.data_storage.method;
    if (typeof method === "function") {
      return method();
    } else {
      return method;
    }
  }

  getWithCredentials() {
    const withCredentials = this.config.data_storage.withCredentials;
    if (typeof withCredentials === "function") {
      return withCredentials();
    } else {
      return withCredentials;
    }
  }

  getCrossDomain() {
    const crossDomain = this.config.data_storage.crossDomain;
    if (typeof crossDomain === "function") {
      return crossDomain();
    } else {
      return crossDomain;
    }
  }

  getHeaders() {
    const headers = this.config.data_storage.headers;
    if (typeof headers === "function") {
      return headers();
    } else {
      return headers;
    }
  }

  checkforStore(content) {
    const isChanged = !Immutable.is(Immutable.fromJS(this.editorContent), Immutable.fromJS(content));
    if (!isChanged) {
      return;
    }
    this.save(content);
  }

  save(content) {
    if (this.config.data_storage.save_handler) {
      this.config.data_storage.save_handler(this, content);
      return;
    }

    if (this.config.xhr.before_handler) {
      this.config.xhr.before_handler();
    }

    return axios({
      method: this.getMethod(),
      url: this.getUrl(),
      data: {
        editor_content: JSON.stringify(content),
        text_content: this.getTextFromEditor(content)
      },
      withCredentials: this.getWithCredentials(),
      crossDomain: this.getCrossDomain(),
      headers: this.getHeaders()
    }).then(result => {
      if (this.config.data_storage.success_handler) {
        return this.config.data_storage.success_handler(result);
      }
      if (this.config.xhr.success_handler) {
        return this.config.xhr.success_handler(result);
      }
    }).catch(error => {
      if (this.config.data_storage.failure_handler) {
        return this.config.data_storage.failure_handler(error);
      }
      if (this.config.xhr.failure_handler) {
        return this.config.xhr.failure_handler(error);
      }
    });
  }
}

